-- KRAVIA Office HR: isolated, source-backed spreadsheet import staging.
-- A workbook never signs, approves, backdates, overwrites or pays any hours.
-- No historical employee rows are generated by this migration.
create table if not exists public.office_hr_attendance_import_batches (
  id uuid primary key default gen_random_uuid(),
  file_name text not null check(length(file_name) between 5 and 180),
  file_sha256 text not null unique check(file_sha256 ~ '^[0-9a-f]{64}$'),
  created_by uuid not null references public.office_identity_users(user_id),
  row_count integer not null check(row_count between 1 and 400),
  status text not null default 'STAGED' check(status in ('STAGED','UNDER_REVIEW','CLOSED')),
  created_at timestamptz not null default now()
);
create table if not exists public.office_hr_attendance_import_rows (
  id uuid primary key default gen_random_uuid(),
  batch_id uuid not null references public.office_hr_attendance_import_batches(id) on delete restrict,
  row_key text not null check(length(row_key) between 5 and 80),
  source_sheet text not null check(source_sheet in ('Aug 2026','Sep 2026','Oct 2026','Nov 2026')),
  source_row integer not null check(source_row between 5 and 2000),
  employee_user_id uuid not null references public.office_identity_users(user_id),
  work_date date not null check(work_date >= date '2026-08-01'),
  payable_candidate_minutes integer not null check(payable_candidate_minutes between 0 and 360),
  paid_leave_candidate_minutes integer not null check(paid_leave_candidate_minutes between 0 and 360),
  overtime_candidate_minutes integer not null check(overtime_candidate_minutes between 0 and 1440),
  evidence_reference text not null check(length(trim(evidence_reference)) between 8 and 500),
  workbook_decision text not null default '',
  source_status text not null default '',
  status text not null default 'PENDING' check(status in ('PENDING','ACCEPTED','REJECTED')),
  reviewed_by uuid references public.office_identity_users(user_id),
  reviewed_at timestamptz,
  review_note text,
  created_at timestamptz not null default now(),
  unique(batch_id,row_key),
  unique(batch_id,employee_user_id,work_date),
  check(payable_candidate_minutes + paid_leave_candidate_minutes <= 360),
  check(payable_candidate_minutes+paid_leave_candidate_minutes+overtime_candidate_minutes>0),
  constraint office_hr_import_independent_review check(
    status<>'ACCEPTED' or (reviewed_by is not null and reviewed_at is not null)
  )
);
-- Prevent two accepted spreadsheet claims for the same person and day,
-- including claims from different uploads. These remain *evidence* only.
create unique index if not exists office_hr_import_accepted_day_unique
  on public.office_hr_attendance_import_rows(employee_user_id,work_date)
  where status='ACCEPTED';
create index if not exists office_hr_import_batch_status_idx
  on public.office_hr_attendance_import_rows(batch_id,status,source_sheet,work_date);
create table if not exists public.office_hr_attendance_import_events (
  id bigint generated always as identity primary key,
  batch_id uuid not null references public.office_hr_attendance_import_batches(id),
  row_id uuid references public.office_hr_attendance_import_rows(id),
  actor_user_id uuid not null references public.office_identity_users(user_id),
  event_type text not null check(event_type in ('STAGED','ROW_ACCEPTED','ROW_REJECTED')),
  metadata jsonb not null default '{}'::jsonb,
  occurred_at timestamptz not null default now()
);
alter table public.office_hr_attendance_import_batches enable row level security;
alter table public.office_hr_attendance_import_rows enable row level security;
alter table public.office_hr_attendance_import_events enable row level security;
revoke all on public.office_hr_attendance_import_batches,
  public.office_hr_attendance_import_rows,
  public.office_hr_attendance_import_events from public,anon,authenticated;
grant select,insert,update on public.office_hr_attendance_import_batches to service_role;
grant select,insert,update on public.office_hr_attendance_import_rows to service_role;
grant select,insert on public.office_hr_attendance_import_events to service_role;
grant usage,select on sequence public.office_hr_attendance_import_events_id_seq to service_role;

-- Bulk staging happens in one transaction: invalid rows roll back the whole
-- batch. An uploaded "APPROVED" string has NO authority here.
create or replace function public.office_hr_attendance_import_stage(
  p_actor uuid,p_file_name text,p_file_sha256 text,p_rows jsonb
) returns uuid language plpgsql security definer set search_path='' as $kravia_import$
declare
  result_id uuid;
  raw jsonb;
  v_employee_id uuid;
  requested_date date;
  minutes_pay integer;
  minutes_leave integer;
  minutes_ot integer;
  day_count integer;
  key text;
  used_keys text[] := array[]::text[];
begin
  if not exists(select 1 from public.office_identity_users
    where user_id=p_actor and status='ACTIVE') then
    raise exception 'Active verified Office identity required'; end if;
  if not public.office_effective_permission(p_actor,'people.update','COMPANY',null,null)
    or not (
      exists(select 1 from public.office_user_roles r where r.user_id=p_actor
        and r.role in ('OWNER','DIRECTOR') and (r.expires_at is null or r.expires_at>now()))
      or exists(select 1 from public.office_user_access_profiles h where
        h.user_id=p_actor and h.profile_code='HR_MANAGER' and h.status='ACTIVE'
        and (h.effective_from is null or h.effective_from<=now())
        and (h.expires_at is null or h.expires_at>now()))
    ) then raise exception 'Independent HR upload permission required'; end if;
  if p_file_name is null or length(p_file_name) not between 5 and 180
    or p_file_name !~* '\.xlsx$'
    or p_file_sha256 !~ '^[0-9a-f]{64}$'
    or jsonb_typeof(p_rows)<>'array' or jsonb_array_length(p_rows) not between 1 and 400
  then raise exception 'Invalid reviewed workbook metadata'; end if;
  insert into public.office_hr_attendance_import_batches(
    file_name,file_sha256,created_by,row_count
  ) values (p_file_name,p_file_sha256,p_actor,jsonb_array_length(p_rows))
  returning id into result_id;
  for raw in select value from jsonb_array_elements(p_rows) loop
    if jsonb_typeof(raw)<>'object' then raise exception 'Malformed workbook row'; end if;
    key:=raw->>'key';
    if key is null or length(key) not between 5 and 80 or key=any(used_keys) then
      raise exception 'Invalid or repeated source row ID'; end if;
    used_keys:=array_append(used_keys,key);
    v_employee_id:=(raw->>'employee_user_id')::uuid;
    requested_date:=(raw->>'work_date')::date;
    minutes_pay:=(raw->>'payable_minutes')::integer;
    minutes_leave:=(raw->>'paid_leave_minutes')::integer;
    minutes_ot:=(raw->>'overtime_candidate_minutes')::integer;
    if requested_date < date '2026-08-01'
      or requested_date > (now() at time zone 'Asia/Kolkata')::date
      or minutes_pay<0 or minutes_leave<0 or minutes_ot<0
      or minutes_pay+minutes_leave>360 or minutes_ot>1440
      or minutes_pay+minutes_leave+minutes_ot=0 then
      raise exception 'Impossible or future source day'; end if;
    if not exists(select 1 from public.office_identity_users
       where user_id=v_employee_id and status='ACTIVE') then
      raise exception 'Workbook beneficiary must be an active Office identity'; end if;
    if not exists(select 1 from public.office_employment_registry
      where identity_user_id=v_employee_id and status in ('ACTIVE','ON_LEAVE')) then
      raise exception 'Planned or unknown employment cannot be uploaded as payable evidence'; end if;
    insert into public.office_hr_attendance_import_rows(
      batch_id,row_key,source_sheet,source_row,employee_user_id,work_date,
      payable_candidate_minutes,paid_leave_candidate_minutes,overtime_candidate_minutes,
      evidence_reference,workbook_decision,source_status
    ) values (
      result_id,key,raw->>'sheet',(raw->>'row')::integer,v_employee_id,requested_date,
      minutes_pay,minutes_leave,minutes_ot,trim(raw->>'evidence_reference'),
      left(coalesce(raw->>'workbook_decision',''),80),
      left(coalesce(raw->>'source_status',''),140)
    );
  end loop;
  insert into public.office_hr_attendance_import_events(
    batch_id,actor_user_id,event_type,metadata
  ) values(result_id,p_actor,'STAGED',
    jsonb_build_object('row_count',jsonb_array_length(p_rows),'sha256',p_file_sha256));
  return result_id;
end; $kravia_import$;

-- Independent acceptance attests only that a source document was inspected.
-- It does not create attendance timestamps, approved leave, overtime, wages,
-- payroll snapshots, payslips or payment instructions.
create or replace function public.office_hr_attendance_import_review(
  p_actor uuid,p_row uuid,p_decision text,p_note text
) returns text language plpgsql security definer set search_path='' as $kravia_import$
declare
  item public.office_hr_attendance_import_rows%rowtype;
  batch public.office_hr_attendance_import_batches%rowtype;
  decision text:=upper(trim(p_decision));
begin
  if decision not in ('ACCEPT','REJECT') or length(trim(coalesce(p_note,'')))<12 then
    raise exception 'Independent review decision with a source-based note is required'; end if;
  if not exists(select 1 from public.office_identity_users
    where user_id=p_actor and status='ACTIVE') then
    raise exception 'An active authorized HR reviewer is required'; end if;
  if not public.office_effective_permission(p_actor,'people.update','COMPANY',null,null)
    or not (
      exists(select 1 from public.office_user_roles r where r.user_id=p_actor
        and r.role in ('OWNER','DIRECTOR') and (r.expires_at is null or r.expires_at>now()))
      or exists(select 1 from public.office_user_access_profiles h where h.user_id=p_actor
        and h.profile_code='HR_MANAGER' and h.status='ACTIVE'
        and (h.effective_from is null or h.effective_from<=now())
        and (h.expires_at is null or h.expires_at>now()))
    ) then raise exception 'Independent HR review permission required'; end if;
  select * into item from public.office_hr_attendance_import_rows where id=p_row for update;
  if not found or item.status<>'PENDING' then raise exception 'Only a pending workbook row can be reviewed'; end if;
  select * into batch from public.office_hr_attendance_import_batches
    where id=item.batch_id for update;
  if p_actor=batch.created_by or p_actor=item.employee_user_id then
    raise exception 'Uploader and beneficiary cannot self-approve workbook evidence'; end if;
  if decision='ACCEPT' then
    if item.paid_leave_candidate_minutes>0 and not exists(
      select 1 from public.office_hr_leave_requests l
      where l.employee_user_id=item.employee_user_id and l.status='APPROVED'
        and item.work_date between l.starts_on and l.ends_on
        and l.minutes_per_weekday>=item.paid_leave_candidate_minutes
    ) then raise exception 'Paid leave requires a separately approved HR policy and leave record'; end if;
    if item.work_date>(now() at time zone 'Asia/Kolkata')::date then
      raise exception 'Future attendance cannot be accepted'; end if;
  end if;
  update public.office_hr_attendance_import_rows set
    status=case when decision='ACCEPT' then 'ACCEPTED' else 'REJECTED' end,
    reviewed_by=p_actor,reviewed_at=now(),review_note=left(trim(p_note),1000)
  where id=p_row;
  update public.office_hr_attendance_import_batches set status='UNDER_REVIEW' where id=batch.id;
  insert into public.office_hr_attendance_import_events(
    batch_id,row_id,actor_user_id,event_type,metadata
  ) values(batch.id,item.id,p_actor,case when decision='ACCEPT' then 'ROW_ACCEPTED' else 'ROW_REJECTED' end,
    jsonb_build_object('note',left(trim(p_note),1000),
      'evidence_reference',item.evidence_reference,
      'not_a_payroll_approval',true));
  return case when decision='ACCEPT' then 'ACCEPTED' else 'REJECTED' end;
end; $kravia_import$;
revoke all on function public.office_hr_attendance_import_stage(uuid,text,text,jsonb)
  from public,anon,authenticated;
revoke all on function public.office_hr_attendance_import_review(uuid,uuid,text,text)
  from public,anon,authenticated;
grant execute on function public.office_hr_attendance_import_stage(uuid,text,text,jsonb) to service_role;
grant execute on function public.office_hr_attendance_import_review(uuid,uuid,text,text) to service_role;
